def shared_subsequence(a: str, b: str) -> int:
    prev = [0] * (len(b) + 1)            # previous row: answers for a shorter prefix of a
    for ch in a:
        cur = [0]
        for j, other in enumerate(b, 1):
            if ch == other:
                cur.append(prev[j - 1] + 1)            # match: extend the diagonal
            else:
                cur.append(max(prev[j], cur[j - 1]))   # drop a character from a or from b
        prev = cur
    return prev[-1]

perf.naive:
def shared_subsequence(a: str, b: str) -> int:
    def best(i: int, j: int) -> int:
        if i == len(a) or j == len(b):
            return 0
        if a[i] == b[j]:
            return 1 + best(i + 1, j + 1)
        return max(best(i + 1, j), best(i, j + 1))
    return best(0, 0)
